import{n as e}from"./rolldown-runtime-Cyuzqnbw.js";import{A as t}from"./framer-Be3hPn0e.js";import{Mr as n,Qn as r,en as i,t as a,wr as o}from"./icons-DTR6_mEc.js";import{n as s,t as c}from"./ArticleLayout-DQfIP276.js";var l,u,d=e((()=>{a(),l=[{"@context":`https://schema.org`,"@type":`Article`,headline:`Assurance trajet retour après achat voiture : que dit la loi ?`,description:`Vous venez d'acheter une voiture ? Le trajet retour doit être assuré immédiatement, sans délai de grâce. Attestation en 5 minutes, dès 1 jour.`,author:{"@type":`Organization`,name:`Evidence Assurances`},publisher:{"@type":`Organization`,name:`AssuTempo`,logo:{"@type":`ImageObject`,url:`https://assutempo.fr/logo.png`}},mainEntityOfPage:`https://assutempo.fr/articles/assurance-trajet-retour-achat-voiture`,datePublished:`2026-07-11`,dateModified:`2026-07-11`},{"@context":`https://schema.org`,"@type":`BreadcrumbList`,itemListElement:[{"@type":`ListItem`,position:1,name:`Accueil`,item:`https://assutempo.fr`},{"@type":`ListItem`,position:2,name:`Articles`,item:`https://assutempo.fr/articles`},{"@type":`ListItem`,position:3,name:`Assurance trajet retour après achat voiture`,item:`https://assutempo.fr/articles/assurance-trajet-retour-achat-voiture`}]},{"@context":`https://schema.org`,"@type":`FAQPage`,mainEntity:[{"@type":`Question`,name:`Dois-je assurer ma voiture avant de quitter le vendeur ?`,acceptedAnswer:{"@type":`Answer`,text:`Oui. La loi n'accorde aucun délai de grâce : la responsabilité civile doit couvrir le véhicule dès le premier trajet, y compris le retour depuis chez le vendeur.`}},{"@type":`Question`,name:`Que risque-t-on à rouler sans assurance après un achat ?`,acceptedAnswer:{"@type":`Answer`,text:`Une amende forfaitaire de 500 €, pouvant atteindre 3 750 € devant un tribunal (article L324-2 du Code de la route), ainsi qu'une prise en charge personnelle des dommages en cas d'accident.`}},{"@type":`Question`,name:`Puis-je m'assurer si la carte grise est encore au nom du vendeur ?`,acceptedAnswer:{"@type":`Answer`,text:`Oui, avec la carte grise du vendeur et le certificat de cession signé. Vous disposez ensuite d'un mois pour mettre la carte grise à votre nom.`}},{"@type":`Question`,name:`Que se passe-t-il si je dépasse le délai d'un mois pour la carte grise ?`,acceptedAnswer:{"@type":`Answer`,text:`Un contrôle routier peut entraîner une amende forfaitaire de 135 €, une infraction distincte et bien plus légère que celle liée au défaut d'assurance.`}}]}],u={slug:`assurance-trajet-retour-achat-voiture`,seo:{title:`Assurance trajet retour après achat voiture`,description:`Vous venez d'acheter une voiture ? Le trajet retour doit être assuré immédiatement, sans délai de grâce. Attestation en 5 minutes, dès 1 jour.`,canonical:`https://assutempo.fr/articles/assurance-trajet-retour-achat-voiture`,jsonLd:l},category:`Achat véhicule`,readTime:`6 min`,updatedDate:`11 juillet 2026`,author:`Evidence Assurances`,headline:`Assurance trajet retour après achat voiture : que dit la loi ?`,immediateAnswer:`Le trajet retour après l'achat d'une voiture doit être assuré : la loi ne prévoit aucun délai de grâce, même pour un simple aller entre le domicile du vendeur et le vôtre. Une assurance temporaire, souscrite avec la carte grise du vendeur et le certificat de cession, couvre le véhicule en quelques minutes, sans attendre que le titre soit à votre nom.`,answerCapsule:{answer:`Le trajet retour doit être assuré : la loi ne prévoit aucun délai de grâce après un achat de voiture, même entre particuliers. Vous pouvez souscrire une assurance temporaire en quelques minutes, à partir de la carte grise du vendeur, sans attendre que le titre soit à votre nom.`,facts:[{anchor:`Art. L211-1`,text:`La responsabilité civile est obligatoire dès la prise de possession du véhicule, y compris pour le tout premier trajet.`},{anchor:`500 €`,text:`Rouler sans assurance expose à une amende forfaitaire de 500 € (jusqu'à 3 750 € en cas de poursuites), au titre de l'article L324-2 du Code de la route.`},{anchor:`1 mois`,text:`C'est le délai pour mettre la carte grise à votre nom ; au-delà, un contrôle peut entraîner une amende distincte de 135 €.`}],updated:`11 juillet 2026`},sections:[{type:`text`,heading:`Peut-on prendre la route tout de suite après avoir acheté sa voiture ?`,paragraphs:[`J'ai signé le certificat de cession un samedi matin, sur le capot de la voiture, pendant que le vendeur vérifiait sur son téléphone que le virement était bien arrivé. Une fois l'argent parti, il m'a tendu les clés et je me suis retrouvé seul devant le véhicule, avec une question toute bête : est-ce que j'ai le droit de rentrer chez moi avec, là, maintenant ?`,`La réponse tient en une phrase : oui, il faut être assuré avant de démarrer, et non, il n'existe aucun délai de grâce. L'article L211-1 du Code des assurances impose une couverture en responsabilité civile dès la prise de possession du véhicule, que le trajet fasse cinq kilomètres ou deux cents. Le jour de l'achat compte comme n'importe quel autre.`,`Ce que j'ignorais, c'est que l'assurance du vendeur ne me protégeait à aucun moment. Son contrat continue de courir à son nom jusqu'à ce qu'il le résilie, mais il ne couvre plus un véhicule qui ne lui appartient plus. Sur la route, j'étais donc seul face au risque, avec ou sans le savoir.`,`Reste le cas qui piège le plus d'acheteurs : les ventes entre particuliers se concluent le soir et le week-end, quand la souscription en ligne classique est fermée. Le Guichet de Nuit AssuTempo couvre ces heures, de 21h à 9h et le dimanche toute la journée : vous déposez votre demande depuis le trottoir, et vous repartez avec une attestation plutôt qu'avec un risque.`],relatedLink:{text:`Achat le soir ou le dimanche : le Guichet de Nuit`,href:`/guichet-de-nuit`}},{type:`alert`,heading:`Ce qu'il faut retenir avant de démarrer`,items:[`Assurance obligatoire dès la prise de possession, quel que soit le trajet (art. L211-1)`,`L'assurance du vendeur ne couvre plus le véhicule une fois la vente conclue`,`Souscription possible avec la carte grise du vendeur et le certificat de cession`,`Un mois pour mettre la carte grise à votre nom à partir de la date de cession`]},{type:`stepflow`,ariaLabel:`S'assurer avant le trajet retour en 4 étapes : durée, véhicule, paiement, attestation`,steps:[{icon:n,label:`Choisissez la durée (1 à 90 j)`},{icon:o,label:`Renseignez le véhicule (carte grise du vendeur + cession)`},{icon:r,label:`Payez en ligne`},{icon:i,label:`Recevez l'attestation (5 min)`}]},{type:`text`,heading:`Que risque-t-on vraiment si on roule sans assurance sur ce trajet ?`,paragraphs:[`J'ai fini par vérifier, parce que la question m'a travaillé sur les quarante minutes de route qui me séparaient de chez moi. Rouler sans assurance est un délit, pas une simple contravention. L'article L324-2 du Code de la route prévoit une amende forfaitaire de 500 €, qui peut grimper jusqu'à 3 750 € si l'affaire est portée devant un tribunal.`,`À cela s'ajoutent des sanctions complémentaires possibles selon la gravité : suspension du permis, confiscation du véhicule. Et surtout, en cas d'accident responsable, c'est votre patrimoine personnel qui indemnise les victimes, sans qu'aucun assureur ne prenne le relais.`,`Un détail qui m'a surpris en creusant le sujet : ces 500 € n'ont rien à voir avec l'amende de 135 € que l'on entend parfois citer à propos de la carte grise. Ce sont deux infractions différentes, avec deux échelles de sanction différentes, et mieux vaut ne pas les confondre au moment de juger le risque réel. Les montants évoluant, service-public.fr reste la source à consulter pour les vérifier avant de partir.`]},{type:`text`,heading:`Comment prouve-t-on qu'on est assuré en cas de contrôle sur ce trajet ?`,paragraphs:[`Autre surprise : je m'attendais à recevoir une carte verte à glisser dans la boîte à gants, comme mes parents l'ont toujours fait. Elle a pourtant disparu en avril 2024. Le contrôle se fait désormais à la plaque, via le Fichier des Véhicules Assurés (FVA), consulté directement par les forces de l'ordre.`,`Ce que reçoit l'acheteur à la place, par email et en quelques minutes, c'est un Mémo Véhicule Assuré à garder avec les papiers du véhicule, ainsi qu'une carte internationale d'assurance automobile, utile si le trajet retour passe par une frontière ou si le véhicule doit rouler à l'étranger peu après l'achat.`]},{type:`text`,heading:`Faut-il attendre que la carte grise soit à mon nom pour m'assurer ?`,paragraphs:[`Non, et c'est la partie rassurante de cette histoire. La souscription d'une assurance temporaire se fait à partir de la carte grise du vendeur, encore à son nom, et du certificat de cession (Cerfa 15776) que vous venez de signer ensemble. Aucun assureur sérieux ne vous demandera d'attendre un nouveau titre qui, de toute façon, met plusieurs semaines à arriver.`,`C'est exactement le mécanisme déjà en place pour un achat classique entre particuliers : le véhicule et le conducteur sont couverts, indépendamment de l'état d'avancement de la carte grise.`],relatedLink:{text:`Assurer un véhicule acheté chez un particulier`,href:`/articles/assurer-vehicule-achete-chez-particulier`}},{type:`checklist`,heading:`Quels documents avoir en main avant de démarrer ?`,items:[`Votre permis de conduire`,`La carte grise du véhicule, même encore au nom du vendeur`,`Le certificat de cession signé (Cerfa 15776)`,`Une attestation d'assurance en cours de validité, obtenue avant le départ`,`Un moyen de paiement pour la souscription en ligne`]},{type:`text`,heading:`Et si je tarde à faire ma carte grise personnelle ?`,paragraphs:[`Là, le calendrier change. Vous disposez d'un mois à partir de la date du certificat de cession pour mettre la carte grise à votre nom. Passé ce délai, un contrôle routier peut donner lieu à une contravention de 4e classe : une amende forfaitaire de 135 €, minorée à 90 € en cas de paiement rapide, majorée au-delà.`,`Dans les faits, aucune amende n'est déclenchée automatiquement par une demande tardive sur le site de l'ANTS : la sanction suppose un contrôle par les forces de l'ordre. Ce n'est pas une raison de traîner, simplement un ordre de grandeur très différent de celui du défaut d'assurance.`],relatedLink:{text:`Préparer sa demande de carte grise`,href:`/carte-grise`}},{type:`text`,heading:`Combien de jours d'assurance choisir pour ce trajet retour ?`,paragraphs:[`Pour ma part, j'ai pris cinq jours : le temps du trajet, un week-end de battement, et de quoi lancer tranquillement mon contrat annuel sans stresser sur les délais administratifs. La formule temporaire se choisit au jour près, de 1 à 90 jours, et rien n'empêche de la prolonger si la carte grise ou l'assurance définitive prennent plus de temps que prévu.`],relatedLink:{text:`Obtenir un devis d'assurance temporaire`,href:`/tarification`}}],faqItems:[{q:`Dois-je assurer ma voiture avant de quitter le vendeur ?`,a:`Oui. La loi n'accorde aucun délai de grâce : la responsabilité civile doit couvrir le véhicule dès le premier trajet, y compris le retour depuis chez le vendeur.`},{q:`Que risque-t-on à rouler sans assurance après un achat ?`,a:`Une amende forfaitaire de 500 €, pouvant atteindre 3 750 € devant un tribunal (article L324-2), ainsi qu'une prise en charge personnelle des dommages en cas d'accident.`},{q:`Puis-je m'assurer si la carte grise est encore au nom du vendeur ?`,a:`Oui, avec la carte grise du vendeur et le certificat de cession signé. Vous avez ensuite un mois pour la mettre à votre nom.`},{q:`Que se passe-t-il si je dépasse le délai d'un mois pour la carte grise ?`,a:`Un contrôle peut entraîner une amende forfaitaire de 135 €, une infraction distincte et bien plus légère que celle liée au défaut d'assurance.`}]}}));function f(){return(0,p.jsx)(c,{data:u})}var p;e((()=>{s(),d(),p=t()}))();export{f as default};